using CloudSharp.Core.Domain.Users;

namespace CloudSharp.Infrastructure.Persistence.Entities;

/// <summary>
/// <c>users</c> 테이블 영속성 모델. Core <see cref="CloudSharp.Core.Domain.Users.User"/> Aggregate와 별개의
/// Infrastructure 전용 모델이며 도메인과 영속성 모델 사이의 변환을 담당한다.
/// </summary>
public sealed class UserEntity
{
    /// <summary>
    /// 내부 PK. <c>BIGINT GENERATED BY DEFAULT AS IDENTITY</c>. 외부에 노출하지 않는다.
    /// </summary>
    public long Id { get; set; }

    /// <summary>
    /// 외부 공개 식별자. Core에서 UUIDv7로 생성하며 DB에는 기본값을 두지 않는다.
    /// </summary>
    public Guid PublicId { get; set; }

    /// <summary>
    /// 표시·통신용 이메일.
    /// </summary>
    public string Email { get; set; } = null!;

    /// <summary>
    /// uniqueness·로그인 비교용 정규화 이메일.
    /// </summary>
    public string NormalizedEmail { get; set; } = null!;

    /// <summary>
    /// 표시 사용자명. 선택값.
    /// </summary>
    public string? UserName { get; set; }

    /// <summary>
    /// 대소문자 비구분 비교용 정규화 사용자명. <see cref="UserName"/>과 함께 null이거나 함께 non-null이어야 한다.
    /// </summary>
    public string? NormalizedUserName { get; set; }

    /// <summary>
    /// 표시명. 최대 100자.
    /// </summary>
    public string? DisplayName { get; set; }

    /// <summary>
    /// 승인된 password hasher 결과.
    /// </summary>
    public string PasswordHash { get; set; } = null!;

    /// <summary>
    /// 시스템 전역 역할.
    /// </summary>
    public SystemRole SystemRole { get; set; }

    /// <summary>
    /// 계정 상태.
    /// </summary>
    public UserStatus Status { get; set; }

    /// <summary>
    /// 전체 세션·credential 검증 버전. 비밀번호 변경·정지·삭제 시 증가한다.
    /// </summary>
    public long SecurityVersion { get; set; }

    /// <summary>
    /// optimistic concurrency version. Core가 증가시킨다.
    /// </summary>
    public long Version { get; set; }

    /// <summary>
    /// 생성 시각. UTC.
    /// </summary>
    public DateTimeOffset CreatedAt { get; set; }

    /// <summary>
    /// 수정 시각. UTC.
    /// </summary>
    public DateTimeOffset UpdatedAt { get; set; }

    /// <summary>
    /// 정지 시각. <see cref="UserStatus.Suspended"/> 상태에서 필수.
    /// </summary>
    public DateTimeOffset? SuspendedAt { get; set; }

    /// <summary>
    /// 삭제 시각. <see cref="UserStatus.Deleted"/> 상태에서 필수.
    /// </summary>
    public DateTimeOffset? DeletedAt { get; set; }

    /// <summary>
    /// 저장된 값으로 독립적인 도메인 snapshot을 복원한다.
    /// </summary>
    public User ToDomain() =>
        User.Reconstitute(
            id: Id,
            publicId: PublicId,
            email: EmailAddress.Reconstitute(Email, NormalizedEmail),
            userName: NormalizedUserName is null
                ? null
                : NormalizedName.Reconstitute(UserName!, NormalizedUserName),
            displayName: DisplayName,
            passwordHash: PasswordHash,
            systemRole: SystemRole,
            status: Status,
            securityVersion: SecurityVersion,
            version: Version,
            createdAt: CreatedAt,
            updatedAt: UpdatedAt,
            suspendedAt: SuspendedAt,
            deletedAt: DeletedAt);

    /// <summary>
    /// 도메인 객체의 ID와 상태를 복사한 새 영속성 모델을 생성한다. 입력 객체는 변경하지 않는다.
    /// </summary>
    public static UserEntity FromDomain(User user)
    {
        ArgumentNullException.ThrowIfNull(user);

        var entity = new UserEntity { Id = user.Id };
        entity.UpdateFrom(user);
        return entity;
    }

    /// <summary>
    /// 기존 영속성 모델의 PK를 유지하면서 도메인 상태를 복사한다.
    /// 버전과 시각은 도메인 값을 그대로 사용하며 EF 추적과 동시성 설정은 repository가 담당한다.
    /// </summary>
    public void UpdateFrom(User user)
    {
        ArgumentNullException.ThrowIfNull(user);

        PublicId = user.PublicId;
        Email = user.Email.Value;
        NormalizedEmail = user.Email.Normalized;
        UserName = user.UserName?.Value;
        NormalizedUserName = user.UserName?.Normalized;
        DisplayName = user.DisplayName;
        PasswordHash = user.PasswordHash;
        SystemRole = user.SystemRole;
        Status = user.Status;
        SecurityVersion = user.SecurityVersion;
        Version = user.Version;
        CreatedAt = user.CreatedAt;
        UpdatedAt = user.UpdatedAt;
        SuspendedAt = user.SuspendedAt;
        DeletedAt = user.DeletedAt;
    }
}
